-- BR-084 확정(CONFIRMED)·지급(PAID)된 정산서는 금액을 바꿀 수 없고 항목도 더할 수 없다. 정산서·회차는 삭제하지 않는다.
CREATE OR REPLACE FUNCTION public.settlement_lock_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION '% 테이블은 삭제할 수 없습니다.', TG_TABLE_NAME;
  END IF;
  IF OLD.status IN ('CONFIRMED', 'PAID') AND (
    NEW.job_count, NEW.gross_sales, NEW.base_pay, NEW.extra_pay, NEW.incentive, NEW.deduction,
    NEW.cash_collected, NEW.taxable_amount, NEW.withholding_tax, NEW.net_pay, NEW.batch_id, NEW.technician_id
  ) IS DISTINCT FROM (
    OLD.job_count, OLD.gross_sales, OLD.base_pay, OLD.extra_pay, OLD.incentive, OLD.deduction,
    OLD.cash_collected, OLD.taxable_amount, OLD.withholding_tax, OLD.net_pay, OLD.batch_id, OLD.technician_id
  ) THEN
    RAISE EXCEPTION '확정된 정산은 수정할 수 없습니다. 다음 회차 조정으로 처리하세요. (BR-084)';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER settlement_lock BEFORE UPDATE OR DELETE ON public.settlement
  FOR EACH ROW EXECUTE FUNCTION public.settlement_lock_guard();
--> statement-breakpoint
CREATE OR REPLACE FUNCTION public.settlement_item_lock_guard() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF EXISTS (SELECT 1 FROM settlement s WHERE s.id = NEW.settlement_id AND s.status IN ('CONFIRMED', 'PAID')) THEN
    RAISE EXCEPTION '확정된 정산에는 항목을 더할 수 없습니다. 다음 회차 조정으로 처리하세요. (BR-084)';
  END IF;
  RETURN NEW;
END $$;
--> statement-breakpoint
CREATE TRIGGER settlement_item_lock BEFORE INSERT ON public.settlement_item
  FOR EACH ROW EXECUTE FUNCTION public.settlement_item_lock_guard();
--> statement-breakpoint
CREATE TRIGGER settlement_batch_no_delete BEFORE DELETE ON public.settlement_batch
  FOR EACH ROW EXECUTE FUNCTION public.forbid_update_delete();
--> statement-breakpoint
